<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Homework</h1><p>Filter, add and update persisted assignments.</p></div></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Date</label><input class="module-input" type="date" name="date" value="<?= e($_GET['date']??'') ?>"></div><div class="module-field"><label>Class</label><select class="module-select" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Teacher</label><select class="module-select" name="teacher"><option value="">All Teachers</option><?php foreach($teachers as$t):?><option value="<?= $t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Filter</button></form><section class="module-card"><header class="module-card__header"><h2>Add Homework</h2></header><div class="module-card__body"><form method="post" action="<?= url('/admin/homework') ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Date</label><input class="module-input" type="date" name="hwdate" value="<?= date('Y-m-d') ?>" required></div><div class="module-field"><label>Teacher</label><select class="module-select" name="hwteacher" required><?php foreach($teachers as$t):?><option value="<?= $t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Class</label><select class="module-select" name="hwclass" required><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Subject</label><select class="module-select" name="hwsubject" required><?php foreach($subjects as$s):?><option value="<?= $s['id'] ?>" data-class="<?= $s['class_id'] ?>"><?= e($s['name']) ?></option><?php endforeach ?></select></div><div class="module-field field--wide"><label>Homework</label><textarea class="module-textarea" name="homework" required></textarea></div><div class="module-field"><label>Attachment</label><input class="module-input" type="file" name="hwattachment" accept=".pdf,.jpg,.jpeg,.png"></div></div><button class="btn btn--primary">Add Homework</button></form></div></section><?php foreach($rows as$h):?><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/homework/'.$h['id']) ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><input type="date" class="module-input" name="hwdate" value="<?= e($h['homework_date']) ?>" required><select class="module-select" name="hwteacher"><?php foreach($teachers as$t):?><option value="<?= $t['id'] ?>" <?= $h['teacher_id']==$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select><select class="module-select" name="hwclass"><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $h['class_id']==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><select class="module-select" name="hwsubject"><?php foreach($subjects as$s):?><option value="<?= $s['id'] ?>" <?= $h['subject_id']==$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach ?></select><textarea class="module-textarea" name="homework" required><?= e($h['homework_text']) ?></textarea><div><?php if($h['attachment_path']):?><a href="<?= asset('../'.$h['attachment_path']) ?>">Attachment</a><?php endif ?><input class="module-input" type="file" name="hwattachment"></div></div><button class="btn btn--secondary">Update</button></form><form method="post" action="<?= e(url('/admin/homework/'.$h['id'].'/delete')) ?>" class="inline-form"><?= csrf_field() ?><button class="btn btn--ghost" type="submit" onclick="return confirm('Delete this homework?')">Delete</button></form></div></section><?php endforeach ?><?php if(!$rows):?><div class="compact-empty"><h3>No Homework Found</h3></div><?php endif ?></div></div></main>
